\set ON_ERROR_STOP on
begin;
create function pg_temp.style_assert(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Style assertion: %',label;end if;end $$;
do $$
declare actor uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); w uuid; fw uuid; req uuid:=gen_random_uuid(); edit_id uuid:=gen_random_uuid(); sid uuid; idea uuid; eid uuid; sample_id uuid:=gen_random_uuid(); p jsonb; input jsonb; bible_input jsonb; result jsonb; sample jsonb; review public.review_requests;
begin
 w:=public.studio_provision(actor,'Style catalogue test',false);fw:=public.studio_provision(outsider,'Foreign styles test',false);
 p:='{"version":"1.0.0","primary_style":"illustrated","continuity_mode":"fixed","allowed_styles":["illustrated"],"source":"automatic","voice_policy":"preserve"}';
 perform pg_temp.style_assert(public.valid_story_presentation(p),'valid legacy-compatible preferences');
 perform pg_temp.style_assert(not public.valid_story_presentation(p||'{"allowed_styles":["illustrated","anime"]}'),'fixed mode rejects multiple styles');
 perform pg_temp.style_assert(not public.valid_story_presentation(p||'{"allowed_styles":["illustrated","illustrated"]}'),'duplicate styles rejected');
 perform pg_temp.style_assert(not public.valid_story_presentation(p||'{"cash_allowed":true}'),'unknown permission rejected');
 input:=jsonb_build_object('kind','fruits','genre','mystery','chapters',2,'premise','Duas frutas encontram uma chave misteriosa na feira.','presentation',p);
 bible_input:='{"kind":"fruits","genre":"mystery","title":"A chave da feira","premise":"Duas frutas encontram uma chave misteriosa na feira.","cast":[{"id":"lia","name":"Lia","appearance":"apple","color":"#ef1234","personality":"Curiosa e amiga de todos.","voice":"female"},{"id":"rui","name":"Rui","appearance":"orange","color":"#fab123","personality":"Impulsivo e muito curioso.","voice":"male"}],"chapters":[{"title":"A chave misteriosa","arc":"Encontram a chave dourada e descobrem quem poderia ter perdido aquele objeto na feira."},{"title":"A porta escondida","arc":"Abrem a porta escondida atrás do portão e descobrem o segredo da feira."}]}';
 perform public.studio_story_claim(w,actor,req,input);sid:=public.studio_story_save(w,actor,req,bible_input);
 perform pg_temp.style_assert(public.studio_story_save(w,actor,req,bible_input)=sid,'proposal retry preserves style version');
 perform pg_temp.style_assert((select count(*)=1 from public.studio_story_presentations where series_id=sid),'one preference revision per proposal');
 result:=public.studio_story_next(w,actor,sid);idea:=(result->>'idea_id')::uuid;
 perform pg_temp.style_assert(result->>'code'='queued','illustrated choice uses existing production');
 perform pg_temp.style_assert((select revision=1 and style_id='illustrated' from public.studio_chapter_presentations where series_id=sid and chapter_number=1),'chapter freezes its preference version');
 perform pg_temp.style_assert(public.studio_story_next(w,actor,sid)->>'idea_id'=idea::text,'repeated next reuses pending chapter');
 perform pg_temp.style_assert(public.studio_story_presentation_save(w,actor,sid,1,edit_id,p,true)->>'code'='chapter_active','pending chapter cannot be restyled');
 begin perform public.studio_story_presentation_save(w,outsider,sid,1,edit_id,p,true);raise exception 'Foreign preference save accepted';exception when insufficient_privilege then null;end;
 result:=public.studio_command(w,actor,gen_random_uuid(),'generate_video',jsonb_build_object('id',idea,'revision',(select revision from public.idea_queue where id=idea)));eid:=(result->>'episode_id')::uuid;
 update public.episodes set status='research',research_data='[]',research_evidence=jsonb_build_object('type','fiction_plan','context',briefing->'story_context') where id=eid;
 update public.episodes set status='script',script_json=jsonb_build_object('fiction',jsonb_build_object('context',briefing->'story_context','summary','Lia e Rui encontraram a chave dourada e uma pista indicando a porta escondida atrás do portão da feira.'),'disclosures',jsonb_build_object('contains_synthetic_media',true,'commercial_content',false)) where id=eid;
 update public.episodes set status='assets' where id=eid;
 update public.episodes set status='rendered',render_url='https://example.test/story.mp4' where id=eid;
 update public.episodes set status='review' where id=eid;
 review:=public.studio_ensure_review(eid);perform public.studio_review_action(w,actor,gen_random_uuid(),review.id,review.fingerprint,'approve');
 p:=p||'{"primary_style":"anime","continuity_mode":"per_chapter","allowed_styles":["anime","illustrated"]}';
 result:=public.studio_story_presentation_save(w,actor,sid,1,edit_id,p,true);
 perform pg_temp.style_assert(result->>'revision'='2' and result->>'effective_from'='2','style change takes effect at next chapter');
 perform pg_temp.style_assert(public.studio_story_presentation_save(w,actor,sid,1,edit_id,p,true)=result,'style edit request is idempotent');
 perform pg_temp.style_assert(public.studio_story_presentation_save(w,actor,sid,1,gen_random_uuid(),p,true)->>'code'='style_changed','stale browser cannot overwrite revision');
 perform pg_temp.style_assert((select s.bible=bible_input from public.studio_series s where id=sid),'style never changes the bible');
 perform pg_temp.style_assert(public.studio_story_next_presented(w,actor,sid,'anime')->>'code'='style_preparation_required','unsupported style never falls through to old illustration');
 perform pg_temp.style_assert((select count(*)=1 from public.studio_story_chapters where series_id=sid),'unavailable style creates no chapter');
 result:=public.studio_story_next_presented(w,actor,sid,'illustrated');
 perform pg_temp.style_assert(result->>'chapter_number'='2','explicitly permitted illustrated variant can continue');
 perform pg_temp.style_assert((select revision=1 from public.studio_chapter_presentations where series_id=sid and chapter_number=1),'previous chapter keeps its version');
 perform pg_temp.style_assert((select revision=2 and style_id='illustrated' from public.studio_chapter_presentations where series_id=sid and chapter_number=2),'new chapter binds chosen allowed style');
 begin update public.studio_story_presentations set preferences=p where series_id=sid and revision=1;raise exception 'Old preferences changed';exception when check_violation then null;end;
 begin update public.studio_chapter_presentations set revision=2 where series_id=sid and chapter_number=1;raise exception 'Old chapter restyled';exception when check_violation then null;end;
 sample:=jsonb_build_object('id',sample_id,'style_id','cinematic_3d','source','auray','title','A real generated sample','model','MiniMax H3 fast','sha256',repeat('a',64),'bytes',100,'seconds',5,'width',768,'height',1344,'output_fps',24,'native_fps',24,'has_audio',true,'motion','generated','review_scope','technical_only','limitations',jsonb_build_array('Continuity still pending.'));
 result:=public.register_story_style_sample(w,sample);
 perform pg_temp.style_assert(public.register_story_style_sample(w,sample)=result,'same sample import reuses immutable slot');
 perform pg_temp.style_assert(jsonb_array_length(public.studio_story_style_gallery(w,actor))=0,'partial upload stays hidden');
 perform public.ready_story_style_sample(w,sample_id,repeat('a',64));perform public.ready_story_style_sample(w,sample_id,repeat('a',64));
 perform pg_temp.style_assert(jsonb_array_length(public.studio_story_style_gallery(w,actor))=1,'ready original sample visible');
 perform pg_temp.style_assert(jsonb_array_length(public.studio_story_style_gallery(fw,outsider))=0,'other workspace has no shared gallery');
 perform pg_temp.style_assert(public.studio_story_style_media(w,actor,sample_id)->>'path'=w||'/story-samples/'||sample_id||'/'||repeat('a',64)||'.mp4','private workspace path derived on server');
 begin perform public.studio_story_style_media(fw,outsider,sample_id);raise exception 'Foreign sample read';exception when no_data_found then null;end;
 begin perform public.register_story_style_sample(fw,sample);raise exception 'Sample transferred';exception when insufficient_privilege then null;end;
 perform pg_temp.style_assert(not has_function_privilege('authenticated','public.register_story_style_sample(uuid,jsonb)','execute'),'browser cannot forge examples');
 perform pg_temp.style_assert(not has_function_privilege('service_role','public.studio_story_next_before_presentation(uuid,uuid,uuid)','execute'),'old entry point is not an adapter bypass');
 perform pg_temp.style_assert(not exists(select 1 from public.studio_video_jobs where workspace_id=w),'preferences and gallery never submit GPU work');
end $$;
rollback;
